-- Schema of database 'hh_appointment' (PostgreSQL 16), generated by Hibernate from the JPA entities.
-- Reference only: the services create/update these tables automatically (spring.jpa.hibernate.ddl-auto=update).

CREATE TABLE public.appointments (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    appointment_date date NOT NULL,
    appointment_number character varying(20),
    appointment_time time(6) without time zone NOT NULL,
    booked_by character varying(255),
    consultation_id bigint,
    health_centre_id bigint NOT NULL,
    health_centre_name character varying(255),
    notes character varying(500),
    priority character varying(15),
    reason character varying(500),
    resident_id bigint NOT NULL,
    resident_name character varying(255),
    status character varying(15),
    type character varying(20) NOT NULL,
    village character varying(255),
    worker_id bigint,
    worker_name character varying(255),
    CONSTRAINT appointments_priority_check CHECK (((priority)::text = ANY ((ARRAY['ROUTINE'::character varying, 'URGENT'::character varying, 'EMERGENCY'::character varying])::text[]))),
    CONSTRAINT appointments_status_check CHECK (((status)::text = ANY ((ARRAY['SCHEDULED'::character varying, 'CHECKED_IN'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'NO_SHOW'::character varying])::text[]))),
    CONSTRAINT appointments_type_check CHECK (((type)::text = ANY ((ARRAY['GENERAL'::character varying, 'ANTENATAL'::character varying, 'IMMUNIZATION'::character varying, 'FOLLOW_UP'::character varying, 'CHRONIC_CARE'::character varying, 'DENTAL'::character varying, 'EYE'::character varying, 'TELECONSULTATION'::character varying])::text[])))
);
ALTER TABLE public.appointments ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.appointments_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.consultation_treatments (
    consultation_id bigint NOT NULL,
    dosage character varying(255),
    duration_days integer,
    frequency character varying(255),
    instructions character varying(255),
    name character varying(255),
    quantity integer,
    treatment_type character varying(255),
    line_no integer NOT NULL,
    CONSTRAINT consultation_treatments_treatment_type_check CHECK (((treatment_type)::text = ANY ((ARRAY['MEDICATION'::character varying, 'PROCEDURE'::character varying, 'LAB_TEST'::character varying, 'THERAPY'::character varying, 'REFERRAL'::character varying, 'COUNSELLING'::character varying])::text[])))
);
CREATE TABLE public.consultations (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    advice character varying(1000),
    appointment_id bigint NOT NULL,
    appointment_number character varying(255),
    blood_pressure character varying(255),
    clinical_notes character varying(2000),
    consultation_date date,
    diagnosis character varying(500) NOT NULL,
    doctor_name character varying(255),
    follow_up_booked boolean,
    follow_up_date date,
    health_centre_id bigint,
    health_centre_name character varying(255),
    pulse integer,
    resident_id bigint,
    resident_name character varying(255),
    spo2 integer,
    symptoms character varying(1000),
    temperaturec double precision,
    weight_kg double precision
);
ALTER TABLE public.consultations ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.consultations_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
ALTER TABLE ONLY public.appointments
    ADD CONSTRAINT appointments_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.consultation_treatments
    ADD CONSTRAINT consultation_treatments_pkey PRIMARY KEY (consultation_id, line_no);
ALTER TABLE ONLY public.consultations
    ADD CONSTRAINT consultations_pkey PRIMARY KEY (id);
CREATE INDEX idxfekijklit8836sb9ikdq208kv ON public.appointments USING btree (appointment_date);
CREATE INDEX idxfkvg3jx25ti9jm57hcj8xfl9e ON public.appointments USING btree (resident_id);
CREATE INDEX idxm2p3vbg6ppshnf7j59wvom2kd ON public.consultations USING btree (resident_id);
CREATE INDEX idxtq3iudqr5ov7a5k6dr770cau4 ON public.consultations USING btree (appointment_id);
ALTER TABLE ONLY public.consultation_treatments
    ADD CONSTRAINT fkjlnv64e8ivmainy523syfl2et FOREIGN KEY (consultation_id) REFERENCES public.consultations(id);
